16: package org.springframework.samples.petclinic.owner.application;
17: 
18: import org.springframework.context.ApplicationEventPublisher;
19: import org.springframework.samples.petclinic.owner.VisitBooked;
20: import org.springframework.samples.petclinic.owner.domain.Owner;
21: import org.springframework.samples.petclinic.owner.domain.OwnerRepository;
22: import org.springframework.samples.petclinic.owner.domain.Visit;
23: import org.springframework.stereotype.Service;
24: import org.springframework.transaction.annotation.Transactional;
25: 
26: /**
27:  * Application service of the {@code owner} module handling visit booking.
28:  * <p>
29:  * After persistence, it publishes a {@link VisitBooked} event so other modules can react
30:  * without direct dependencies on this module.
31:  */
32: @Service
33: public class VisitScheduler {
34: 
35: 	private final OwnerRepository owners;
36: 
37: 	private final ApplicationEventPublisher eventPublisher;
38: 
39: 	public VisitScheduler(OwnerRepository owners, ApplicationEventPublisher eventPublisher) {
40: 		this.owners = owners;
41: 		this.eventPublisher = eventPublisher;
42: 	}
43: 
44: 	@Transactional
45: 	public void bookVisit(Owner owner, Integer petId, Visit visit) {
46: 		Owner managedOwner = owners.findById(owner.getId()).orElseThrow();
47: 		managedOwner.addVisit(petId, visit);
48: 		owners.flush();
49: 		eventPublisher.publishEvent(new VisitBooked(visit.getId(), petId, visit.getDate()));
50: 	}
51: 
52: }

