16: package org.springframework.samples.petclinic.vet.internal;
17: 
18: import org.springframework.context.event.EventListener;
19: import org.springframework.modulith.events.ApplicationModuleListener;
20: import org.springframework.modulith.moments.DayHasPassed;
21: import org.springframework.samples.petclinic.owner.VisitBooked;
22: import org.springframework.stereotype.Component;
23: 
24: /**
25:  * Listener of the {@code vet} module reacting to visits booked by the {@code owner} and
26:  * to Passage of Time events published by Spring Modulith Moments.
27:  * <p>
28:  * It demonstrates event-driven decoupling: the {@code owner} module does not know the
29:  * {@code vet} module. Communication happens only through the {@link VisitBooked} event,
30:  * which is part of the {@code owner} module public API.
31:  */
32: @Component
33: class VetEventListener {
34: 
35: 	private final VetRoster vetRoster;
36: 
37: 	VetEventListener(VetRoster vetRoster) {
38: 		this.vetRoster = vetRoster;
39: 	}
40: 
41: 	@ApplicationModuleListener
42: 	void on(VisitBooked event) {
43: 		vetRoster.assignVet(event);
44: 	}
45: 
46: 	@EventListener
47: 	void on(DayHasPassed event) {
48: 		vetRoster.cleanupPastAssignments(event.getDate());
49: 	}
50: 
51: }

35:  * It also supports daily cleanup of past assignments triggered by the
36:  * {@link org.springframework.modulith.moments.DayHasPassed} Passage of Time event: once a
37:  * visit date has passed the corresponding row is deleted so the load-balancing counts
38:  * stay accurate.
39:  */
40: @Service
41: class VetRoster {
42: 
43: 	private static final Logger log = LoggerFactory.getLogger(VetRoster.class);
44: 
45: 	private final VetRepository vets;
46: 
47: 	private final VisitAssignmentRepository visitAssignments;
48: 
49: 	VetRoster(VetRepository vets, VisitAssignmentRepository visitAssignments) {
50: 		this.vets = vets;
51: 		this.visitAssignments = visitAssignments;
52: 	}
53: 
54: 	/**
55: 	 * Assigns the least-loaded veterinarian to the visit described by the given event.
56: 	 * Only <em>upcoming</em> assignments (visit date &ge; today) are considered when
57: 	 * computing the workload.
58: 	 * @param event the published {@link VisitBooked} event
59: 	 * @throws IllegalStateException if no vet is registered in the system
60: 	 */
61: 	@Transactional
62: 	void assignVet(VisitBooked event) {
63: 		LocalDate visitDate = event.date();
64: 		Vet assignedVet = vets.findAll()
65: 			.stream()
66: 			.min(Comparator
67: 				.comparingLong(vet -> visitAssignments.countByVetAndVisitDateGreaterThanEqual(vet, visitDate)))
68: 			.orElseThrow(() -> new IllegalStateException("No veterinarian available for assignment"));
69: 
70: 		visitAssignments.save(new VisitAssignment(event.visitId(), assignedVet, visitDate));
71: 
72: 		log.info("Visit {} (pet {}, {}) assigned to Dr. {} {}", event.visitId(), event.petId(), visitDate,
73: 				assignedVet.getFirstName(), assignedVet.getLastName());
74: 	}
75: 
76: 	/**
77: 	 * Removes all visit assignments whose visit date is strictly before {@code today}.
78: 	 * Intended to be called daily via a {@code DayHasPassed} event listener.
79: 	 * @param today the current date (as provided by the Passage of Time event)
80: 	 */
81: 	@Transactional
82: 	void cleanupPastAssignments(LocalDate today) {
83: 		long deleted = visitAssignments.deleteByVisitDateBefore(today);
84: 		if (deleted > 0) {
85: 			log.info("Cleaned up {} past visit assignment(s) (before {})", deleted, today);
86: 		}
87: 	}
88: 
89: }
